package com.example.secretmanagement;

import java.util.Collection;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.annotation.Pointcut;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

interface SecretService {
    String encrypt(String data);
    String decrypt(String data);
}

class DummySecretService implements SecretService {
    public String encrypt(String data) {
        // Dummy encryption logic
        return "encrypted_" + data;
    }

    public String decrypt(String data) {
        // Dummy decryption logic
        return data.replace("encrypted_", "");
    }
}

@Component
@Aspect
public class SecretManager {

    private static final Logger LOGGER = LoggerFactory.getLogger(SecretManager.class);

    private final SecretService secretService;

    public SecretManager(SecretService secretService) {
        this.secretService = secretService;
    }

    @Pointcut("execution(public * com.example.repository..*.save(..)) && args(entity)")
    public void onRepositorySave(Object entity) {
    }

    @Pointcut("execution(public * com.example.repository..*.saveAll(..)) && args(entities)")
    public void onRepositorySaveAll(Collection<?> entities) {
    }

    @Pointcut("execution(public * com.example.repository..*.findById(..)) && args(id)")
    public void onRepositoryFindById(Object id) {
    }

    @Around("onRepositorySave(entity)")
    public Object proceedOnRepositorySave(ProceedingJoinPoint proceedingJoinPoint, Object entity) throws Throwable {
        if (entity instanceof Encryptable) {
            ((Encryptable) entity).encryptSensitiveFields(secretService);
        }
        Object result = proceedingJoinPoint.proceed();
        if (result instanceof Encryptable) {
            ((Encryptable) result).decryptSensitiveFields(secretService);
        }
        return result;
    }

    @Around("onRepositorySaveAll(entities)")
    public Object proceedOnRepositorySaveAll(ProceedingJoinPoint proceedingJoinPoint, Collection<?> entities) throws Throwable {
        entities.stream()
                .filter(e -> e instanceof Encryptable)
                .forEach(e -> ((Encryptable) e).encryptSensitiveFields(secretService));
        Object result = proceedingJoinPoint.proceed();
        if (result instanceof Collection) {
            ((Collection<?>) result).stream()
                    .filter(e -> e instanceof Encryptable)
                    .forEach(e -> ((Encryptable) e).decryptSensitiveFields(secretService));
        }
        return result;
    }

    @Around("onRepositoryFindById(id)")
    public Object proceedOnRepositoryFindById(ProceedingJoinPoint proceedingJoinPoint, Object id) throws Throwable {
        Object result = proceedingJoinPoint.proceed();
        if (result instanceof Encryptable) {
            ((Encryptable) result).decryptSensitiveFields(secretService);
        }
        return result;
    }
}

